<script lang="ts">
 import{onMount}from"svelte";import AppIcon from"../components/AppIcon.svelte";import WindowFrame from"../components/WindowFrame.svelte";import{applyChromeInsets,openWindow,setLauncherOpen,setNotificationCenterOpen,shellStore}from"../../appshell/lib/store";import{setActiveSpace,SPACE_IDS,spaceOf}from"../../appshell/lib/spaces-core";import{groupTop}from"../../appshell/lib/window-tabs-core";import{setSpotlightOpen}from"../../appshell/lib/store-panels";import type{AppDescriptor}from"../types";
 let{apps,brand}:{apps:AppDescriptor[];brand:{name:string;logo?:string;idleAppName?:string}}=$props();let v=$state(0);onMount(()=>{applyChromeInsets({top:30,bottom:92});const u=shellStore.subscribe(()=>v++);return()=>{u();applyChromeInsets({})}});let order=$derived((v,shellStore.getOrder()));let focused=$derived((v,shellStore.getFocused()));let activeSpace=$derived((v,shellStore.getActiveSpace()));let wins=$derived(order.map(id=>shellStore.getWindow(id)).filter(w=>w&&!w.minimized&&spaceOf(w)===activeSpace&&(!w.groupId||groupTop(w.groupId)===w.id)));let focusedWin=$derived(focused?shellStore.getWindow(focused):undefined);let active=$derived(apps.find(a=>a.id===focusedWin?.app));let dock=$derived(apps.filter(a=>!a.noDock).slice(0,12));const launch=(a:AppDescriptor)=>openWindow(a.id,a.title,a.defaultSize,undefined,{multi:a.multi});
</script>
<div class="shell mac" data-shell="macos">
