 <main class="desktop"><div class="icons">{#each apps.filter(a=>!a.noDock).slice(0,8) as app (app.id)}<AppIcon {app} onclick={()=>launch(app)}/>{/each}</div>{#each wins as win (win.id)}{@const app=apps.find(a=>a.id===win.app)}{#if app}<WindowFrame {win} {app} shell="macos"/>{/if}{/each}</main>
