<style>.shell{position:absolute;inset:0;color:white}.menubar{height:30px;display:flex;align-items:center;gap:7px;padding:0 10px;background:#10101499;backdrop-filter:blur(24px);font-size:12px}.menubar>span{flex:1}.menubar button{border:0;background:transparent;color:inherit;padding:4px 6px;border-radius:6px}.menubar button:hover,.menubar .current{background:#ffffff20}.brand{font-weight:800}.desktop{position:absolute;inset:30px 0 0;overflow:hidden}.icons{position:absolute;right:14px;top:14px;z-index:2;display:grid;grid-template-columns:repeat(2,78px);gap:14px}.dock{position:absolute;z-index:800;bottom:12px;left:50%;transform:translateX(-50%);display:flex;align-items:end;gap:8px;padding:8px 10px;border:1px solid #ffffff4a;border-radius:18px;background:#ffffff24;backdrop-filter:blur(26px);box-shadow:0 16px 45px #0005}.launch{width:48px;height:48px;border:0;border-radius:14px;background:#ffffff25;color:white;font-size:20px}time{white-space:nowrap}</style>
